final class ContextSignedUnaryBranchMatrix {
 static int checks;static final int WORK=64000000;
 static void require(boolean b,String why){++checks;if(!b)throw new AssertionError(why);}
 interface Attempt{void run()throws Exception;}
 static void reject(Attempt a,String why)throws Exception{boolean failed=false;try{a.run();}catch(Exception expected){failed=true;}require(failed,why);}
 static boolean[] f(boolean a,boolean b){return new boolean[]{a,b};}
 static Snapshot bind(boolean x,String text)throws Exception{return ContextSignedUnaryModelMatrix.bind(x,text);}
 static Map<String,List<Boolean>> truth(Object... v){return ContextSignedUnaryModelMatrix.truth(v);}
 static Interpretation m(SemanticTermSnapshot v,Map<Source,Integer> w,Object... cells){return ContextSignedUnaryModelMatrix.m(v,w,cells);}
 static Map<Cut,Interpretation> models(Snapshot x,Interpretation self,Object... cuts){return ContextSignedUnaryModelMatrix.models(x,self,cuts);}
 static Policy policy(){return new Policy(65536,WORK,64);}
 static Set<Origin> origins(ContextSignedWitnessNativeBranch.Receipt branch,Cut cut){Set<Origin> out=new LinkedHashSet<>();ContextSignedWitnessContinuationScope.Receipt s=branch.termination.result.output;for(Item i:s.current().packet.items)for(Slot t:i.atom.arguments)if(t.origin!=null)out.add(t.origin);PrivatePool p=s.current().privatePools.get(cut);if(p!=null)for(Item i:p.local.items)for(Slot t:i.atom.arguments)if(t.origin!=null)out.add(t.origin);for(ContextUniversalSignedUnitExchange.Unit u:branch.termination.result.stopping.units.units)out.addAll(u.clause.origins);for(ContextUniversalCompoundExchange.ResidualProof c:branch.termination.result.stopping.compounds.clauses)out.addAll(c.clause.origins);for(ContextUniversalFrozenConstraints.Proof p0:branch.termination.result.terminal.checks.get(cut).proofs)if(p0.clause!=null)out.addAll(p0.clause.origins);return out;}
 static Map<Cut,Extension> extensions(ContextSignedWitnessNativeBranch.Receipt branch){Map<Cut,Extension> out=new LinkedHashMap<>();for(Cut cut:branch.termination.result.terminal.checks.keySet()){Map<Origin,Integer> map=new LinkedHashMap<>();for(Origin o:origins(branch,cut))map.put(o,0);out.put(cut,new Extension(Collections.emptyMap(),map));}return out;}
 static final class Fixture {
  final Snapshot x,a;final List<Snapshot> fs;final Map<Cut,Interpretation> models;final ContextSignedUnaryModelAudit.Receipt original;final ContextSignedWitnessNativeBranch.Receipt branch;final Map<Cut,Extension> extensions;final Policy p=policy();
  Fixture(boolean newPredicate)throws Exception{SemanticTermSnapshot one=ContextSignedUnaryModelMatrix.one();if(newPredicate){x=bind(true,"!anchor(1); !$u seed(u);");a=bind(false,"!@u seed(u)->~blocked(u);");Map<Source,Integer> w=Collections.singletonMap(x.primary.stream().filter(e->e.bundle!=null).findFirst().get().source,0);models=models(x,m(one,w,"anchor",f(true,false),"seed",f(true,false)),a,m(one,w,"anchor",f(true,false),"seed",f(true,false),"blocked",f(false,false)));}else{x=bind(true,"!anchor(1); !@u p(u); !@u seed(u)->~blocked(u);");a=bind(false,"!$u seed(u)&&~blocked(u);");models=models(x,m(one,Collections.emptyMap(),"anchor",f(true,false),"p",f(true,true),"seed",f(false,false),"blocked",f(false,false)),a,m(one,Collections.singletonMap(a.primary.get(0).source,0),"anchor",f(true,false),"p",f(true,true),"seed",f(true,false),"blocked",f(false,false)));}fs=Collections.singletonList(a);ContextSignedUnaryModel.Policy modelPolicy=ContextSignedUnaryModelMatrix.policy();ContextSignedUnaryModel.Result model=ContextSignedUnaryModel.run(x,fs,models,modelPolicy);require(model.status==ContextSignedUnaryModel.Status.MODELLED_SUPPLIED_UNARY,model.reason);original=model.output;ContextSignedWitnessNativeBranch.Result nativeResult=ContextSignedWitnessNativeBranch.run(x,fs,ContextSignedWitnessNativeMatrix.policy());require(nativeResult.status==ContextSignedWitnessNativeBranch.Status.QUIESCENT_SUPPLIED,nativeResult.phase+": "+nativeResult.reason);branch=nativeResult.output;extensions=extensions(branch);if(newPredicate){Extension old=extensions.get(Cut.of(x));extensions.put(Cut.of(x),new Extension(truth("blocked",f(false,false)),old.denotations));}}
 }
 static ContextSignedUnaryBranchModelAudit.Receipt yes(Fixture f){Result r=ContextSignedUnaryBranchModel.run(f.original,f.branch,f.extensions,f.p);require(r.status==Status.SATISFIED_FINAL_UNARY&&r.output!=null,r.phase+": "+r.reason);ContextSignedUnaryBranchModelAudit.check(r.output,f.original,f.branch,f.extensions,f.p,WORK);require(true,"fresh exact original/final proof and semantic audit");return r.output;}
 static void no(Result r,String why){require(r.status==Status.INCOMPLETE&&r.output==null,why+": no partial final model or logical refutation");}
 static void positive()throws Exception{Fixture f=new Fixture(false);ContextSignedUnaryBranchModelAudit.Receipt r=yes(f);Set<Kind> kinds=new HashSet<>();for(Obligation o:r.ledger.obligations)kinds.add(o.kind);require(kinds.equals(EnumSet.allOf(Kind.class)),"ACTUAL common/private/unit/compound/terminal inventories ALL nonempty and covered");require(f.branch.termination.result.output.current().packet.items.stream().anyMatch(i->i.atom.predicate.equals("blocked")&&!i.atom.positive&&i.proofs.stream().anyMatch(p->p.sources.size()==2)),"real signed production from X rule+private bundle is shared");require(f.extensions.get(Cut.of(f.x)).denotations.keySet().stream().anyMatch(o->o.source.equals(f.a.primary.get(0).source))&&f.original.ledger.models.get(Cut.of(f.x)).witnesses.isEmpty(),"self model explicitly denotes an IMPORTED foreign Origin, not an original self binder");require(r.ledger.obligations.stream().filter(o->o.kind==Kind.PRIVATE).count()>f.branch.termination.result.output.current().privatePools.get(Cut.of(f.a)).local.items.size(),"EVERY actual Source alternative retained, not one semantic atom representative");System.out.println("SIGNED_UNARY_FINAL_POSITIVE actualFiveInventories=true realSharedNegativeProduct=true importedForeignOrigin=true allSourceAlternatives=true noWriterIntegration=true");}
 static void extension()throws Exception{Fixture f=new Fixture(true);ContextSignedUnaryBranchModelAudit.Receipt r=yes(f);require(!f.original.ledger.models.get(Cut.of(f.x)).truth.containsKey("blocked")&&f.extensions.get(Cut.of(f.x)).truth.containsKey("blocked"),"new shared predicate gets separate extension, original model unchanged");Map<Cut,Extension> wrong=new LinkedHashMap<>(f.extensions);Extension old=wrong.get(Cut.of(f.x));wrong.put(Cut.of(f.x),new Extension(truth("blocked",f(true,false)),old.denotations));no(ContextSignedUnaryBranchModel.run(f.original,f.branch,wrong,f.p),"original row model and real native stop do NOT imply supplied extension satisfies shared negative product");wrong.put(Cut.of(f.x),new Extension(truth("blocked",f(false,false),"seed",f(true,false)),old.denotations));no(ContextSignedUnaryBranchModel.run(f.original,f.branch,wrong,f.p),"cannot overwrite even equal-valued original truth cell");Map<Cut,Interpretation> reordered=new LinkedHashMap<>();reordered.put(Cut.of(f.a),f.models.get(Cut.of(f.a)));reordered.put(Cut.of(f.x),f.models.get(Cut.of(f.x)));ContextSignedUnaryModel.Result other=ContextSignedUnaryModel.run(f.x,f.fs,reordered,f.original.ledger.policy);require(other.status==ContextSignedUnaryModel.Status.MODELLED_SUPPLIED_UNARY,"logical model map order irrelevant");Result same=ContextSignedUnaryBranchModel.run(other.output,f.branch,f.extensions,f.p);require(same.status==Status.SATISFIED_FINAL_UNARY,"actual final cut order independent of interpretation map iteration order");require(r.ledger.branch==f.branch&&r.ledger.original==f.original,"exact actual input receipts retained");System.out.println("SIGNED_UNARY_FINAL_EXTENSION originalReceiptNotEnough=true importedPredicateTruthRequired=true noOriginalOverride=true canonicalActualCutOrder=true");}
 static void boundary()throws Exception{Fixture f=new Fixture(false);Map<Cut,Extension> missing=new LinkedHashMap<>(f.extensions);missing.remove(Cut.of(f.a));no(ContextSignedUnaryBranchModel.run(f.original,f.branch,missing,f.p),"lost logical cut");Extension self=f.extensions.get(Cut.of(f.x));missing=new LinkedHashMap<>(f.extensions);missing.put(Cut.of(f.x),new Extension(Collections.emptyMap(),Collections.emptyMap()));no(ContextSignedUnaryBranchModel.run(f.original,f.branch,missing,f.p),"missing imported Origin denotation");no(ContextSignedUnaryBranchModel.run(f.original,f.branch,f.extensions,new Policy(1,WORK,64)),"whole final obligation capacity");no(ContextSignedUnaryBranchModel.run(f.original,f.branch,f.extensions,new Policy(65536,1,64)),"fresh model/final audit work");Map<Cut,Extension> extra=new LinkedHashMap<>(f.extensions);extra.put(Cut.of(f.x),new Extension(truth("unused",f(false,false)),self.denotations));no(ContextSignedUnaryBranchModel.run(f.original,f.branch,extra,f.p),"unaccounted new predicate");Extension foreign=f.extensions.get(Cut.of(f.a));Map<Origin,Integer> bad=new LinkedHashMap<>(foreign.denotations);for(Origin o:bad.keySet())bad.put(o,1);extra=new LinkedHashMap<>(f.extensions);extra.put(Cut.of(f.a),new Extension(Collections.emptyMap(),bad));no(ContextSignedUnaryBranchModel.run(f.original,f.branch,extra,f.p),"invalid concrete point/original bundle assignment");
  SemanticTermSnapshot two=ContextSignedEligibilityMatrix.value(2);Map<Cut,Interpretation> expanded=new LinkedHashMap<>();for(Map.Entry<Cut,Interpretation> entry:f.original.ledger.models.entrySet()){Map<String,List<Boolean>> cells=new LinkedHashMap<>();for(Map.Entry<String,List<Boolean>> cell:entry.getValue().truth.entrySet())cells.put(cell.getKey(),Arrays.asList(cell.getValue().get(0),cell.getValue().get(1),cell.getValue().get(1)));expanded.put(entry.getKey(),new Interpretation(Arrays.asList(entry.getValue().points.get(0),two),cells,entry.getValue().witnesses));}ContextSignedUnaryModel.Result originalTwo=ContextSignedUnaryModel.run(f.x,f.fs,expanded,f.original.ledger.policy);require(originalTwo.status==ContextSignedUnaryModel.Status.MODELLED_SUPPLIED_UNARY,"same original interpretation extended with explicit second named point");Map<Cut,Extension> changed=new LinkedHashMap<>(f.extensions);Map<Origin,Integer> assignments=new LinkedHashMap<>(foreign.denotations);for(Origin key:assignments.keySet())assignments.put(key,1);changed.put(Cut.of(f.a),new Extension(Collections.emptyMap(),assignments));Result invalid=ContextSignedUnaryBranchModel.run(originalTwo.output,f.branch,changed,f.p);no(invalid,"VALID different named point cannot replace original whole-bundle assignment");require(invalid.reason.contains("Original whole-bundle assignment cannot change"),"exact original assignment check precedes semantic truth evaluation");
  Object originalOutput=ContextSignedWitnessBarrierMatrix.replace(f.branch.termination.result,"output",f.branch.start);try{no(ContextSignedUnaryBranchModel.run(f.original,f.branch,f.extensions,f.p),"historical/root scope cannot replace ACTUAL final barrier");}finally{ContextSignedWitnessBarrierMatrix.replace(f.branch.termination.result,"output",originalOutput);}Result restored=ContextSignedUnaryBranchModel.run(f.original,f.branch,f.extensions,f.p);require(restored.status==Status.SATISFIED_FINAL_UNARY,"restored actual branch freshly verifies");System.out.println("SIGNED_UNARY_FINAL_BOUNDARY exactCutsOriginsBasisAndObligationBounds=true wrongScopeRejected=true incompleteNotConflict=true");}
 static Object replace(Object o,String field,Object value)throws Exception{return ContextSignedWitnessBarrierMatrix.replace(o,field,value);}
 static void integrity()throws Exception{Fixture f=new Fixture(false);ContextSignedUnaryBranchModelAudit.Receipt r=yes(f);reject(()->ContextSignedUnaryBranchModelAudit.check(r,f.original,f.branch,f.extensions,policy(),WORK),"different exact policy");reject(()->ContextSignedUnaryBranchModelAudit.check(r,f.original,f.branch,f.extensions,f.p,1),"fresh full audit budget");Object old=replace(r.ledger,"obligations",Collections.emptyList());reject(()->ContextSignedUnaryBranchModelAudit.check(r,f.original,f.branch,f.extensions,f.p,WORK),"lost ALL actual final obligations");replace(r.ledger,"obligations",old);List<Obligation> lost=new ArrayList<>(r.ledger.obligations);lost.remove(lost.size()-1);old=replace(r.ledger,"obligations",lost);reject(()->ContextSignedUnaryBranchModelAudit.check(r,f.original,f.branch,f.extensions,f.p,WORK),"lost one actual terminal Source/grade alternative");replace(r.ledger,"obligations",old);Obligation o=r.ledger.obligations.stream().filter(z->z.kind==Kind.UNIT).findFirst().get();old=replace(o,"carrier",f.branch.termination.result.output.units().units.get(0));reject(()->ContextSignedUnaryBranchModelAudit.check(r,f.original,f.branch,f.extensions,f.p,WORK),"previous equal-valued carrier cannot replace fresh final owner");replace(o,"carrier",old);
  Item alternative=f.branch.termination.result.output.current().privatePools.values().stream().flatMap(p->p.local.items.stream()).filter(i->i.proofs.size()>1).findFirst().get();List<org.kanger.ContextProductionCapture.Support> removed=new ArrayList<>(alternative.proofs);removed.remove(removed.size()-1);old=replace(alternative,"proofs",removed);reject(()->ContextSignedUnaryBranchModelAudit.check(r,f.original,f.branch,f.extensions,f.p,WORK),"actual proof inventory loss cannot hide behind old semantic manifest");replace(alternative,"proofs",old);ContextSignedUnaryBranchModelAudit.check(r,f.original,f.branch,f.extensions,f.p,WORK);require(true,"restored actual proof graph/extension freshly verifies");reject(()->r.ledger.extensions.clear(),"immutable cut extensions");reject(()->f.extensions.get(Cut.of(f.x)).denotations.clear(),"immutable Source/binder denotations");System.out.println("SIGNED_UNARY_FINAL_INTEGRITY exactOriginalAndFinalReceipts=true noHistoricalCarrierSubstitution=true everyActualSourceAlternativeChecked=true freshIndependentAudit=true");}
}
